{"path": "creative_intent.json", "content": "{
  "user_need": "1992年，男主是倒爷（个体户），骑嘉陵摩托穿州过省做生意，女主是国营厂下岗女工。他让她坐在后座押货，从南方到北方，七天七夜。她以为是雇佣关系，其实他在进行一场\"流浪婚礼\"——每经过一个县城就供销社买一对枕巾（内部鸳鸯图案），堆满了摩托车的边斗。最后一天他告诉她\"如果这单赚了，我娶你；如果赔了，摩托归你，我归摩托（死在路上）\"。结果是赔了，但她把摩托卖了，买了两张去深圳的车票。场景：嘉陵摩托车（移动封闭空间，风雨中的金属茧）物件：枕巾（商品→聘礼→地图标记，状态：批量→一对→盖在他们头上避雨）；边斗（货仓→婚房→棺材隐喻）疯点：他在暴风雨中停车，只是为了给她买一顶红丝巾（怕她冷）；她会在经过一个城市时偷偷在地图上画心；最后一夜他们在桥洞下过夜，他把所有枕巾铺开当床，说\"现在我们有一万张婚床\"单频振动：漂泊的确定（从雇佣→共谋→定情→新生）篇幅：6500-10000字",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": [
      "牺牲",
      "博弈",
      "漂泊"
    ],
    "scene_elements": [
      "1992年",
      "嘉陵摩托",
      "暴风雨",
      "枕巾",
      "边斗"
    ],
    "relationship_tension": [
      "雇佣与被雇佣",
      "暗恋与共谋",
      "生存与死亡"
    ],
    "user_preferences": {
      "desired_emotion": "彻底的虐心/BE/时代洪流下的无力感",
      "forbidden": [
        "不要大团圆结局",
        "不要机械降神"
      ]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "D22",
    "x_axis_mode_name": "为激情牺牲一切",
    "y_axis_tags": [
      "双向暗恋",
      "商战权谋"
    ],
    "reaction_strength": "↘",
    "tension_stars": 5,
    "forbidden_elements": [
      "不要HE",
      "不要两人一起去深圳"
    ],
    "x_axis_display": "男主以命做赌注，最终输给了时代，履行了'我归摩托'的诺言，只留下女主一人。",
    "y_axis_combination_effect": "商战的残酷（赔了就死）与双向暗恋的纯粹形成剧烈反差，结局的BE将无力感推向顶峰。",
    "reaction_formula": "在必死的赌局中，他用自己的毁灭换取了她的生路。",
    "platform_fit": [
      "知乎盐选",
      "豆瓣阅读"
    ]
  },
  "one_sentence_synopsis": "1992年，倒爷男主带下岗女主骑摩托北上，七天七夜的流浪婚礼终成诀别，他履行赌约死在路上，独留她带着记忆去往深圳。"
}"}

{"content": "{
  "act_one": {
    "description": "第一幕：开篇（0-1500字）- 建立世界观、引入主角和核心冲突",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "暴雨前的金属茧",
        "core_event": "南方湿热的雨季，陈锋用摩托车带走刚下岗的林晚。他在第一个县城买了第一对枕巾，谎称是“紧俏货”。",
        "emotional_tone": "压抑、潮湿、未知的紧张感",
        "key_scenes": [
          "工厂倒闭的公告栏前，陈锋骑着嘉陵摩托出现",
          "林晚第一次坐上摩托车后座，手不知道往哪放",
          "供销社买枕巾，陈锋的眼神闪躲"
        ]
      }
    ],
    "turning_point": "摩托车驶出熟悉的城市，进入未知的公路，两人命运捆绑。"
  },
  "act_two": {
    "description": "第二幕：挣扎（1500-5000字）- 冲突升级、主角陷入困境与情感升温",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "红色丝巾与流浪的锚",
        "core_event": "途经中部省份遭遇暴风雨，陈锋冒雨停车只为给她买一条红丝巾。她在地图上经过的城市画下第一颗心。",
        "emotional_tone": "激烈、浪漫、危险",
        "key_scenes": [
          "暴风雨中摩托车像一片树叶",
          "陈锋全身湿透买回红丝巾，笨拙地给她系上",
          "林晚在地图上偷偷画心，被雨水晕开"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "一万张婚床",
        "core_event": "到达黄河边的桥洞过夜。陈锋铺开所有积攒的鸳鸯枕巾，两人躺在“一万张婚床”上。他半开玩笑半认真地说出那个赌约。",
        "emotional_tone": "绝望中的极致浪漫、悲剧预警",
        "key_scenes": [
          "桥洞下铺满的鸳鸯枕巾，像一场荒诞的婚礼",
          "陈锋说出“摩托归你，我归摩托”的赌约",
          "两人在枕巾堆中沉默相拥，没有说破的爱意"
        ]
      }
    ],
    "turning_point": "赌约确立，情感达到顶峰，但现实的阴影逼近。"
  },
  "act_three": {
    "description": "第三幕：高潮+结局（5000-8000字）- X-Y化学反应爆发，BE结局",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "凛冬的告别",
        "core_event": "抵达北方，生意惨败（被骗）。陈锋为了不连累林晚，故意激怒她或趁她熟睡离开，独自去面对债主/危险，最终死在路上（或失踪）。林晚醒来只看到留下的摩托车和枕巾。",
        "emotional_tone": "冰冷、撕裂、无尽的悲凉",
        "key_scenes": [
          "北方寒风中，接头人老张的骗局揭穿",
          "陈锋最后的决绝眼神，他选择履行“我归摩托”",
          "林晚独自一人在雪地里，守着摩托车和一堆枕巾",
          "结局：林晚卖掉摩托，买了一张去深圳的车票，带着红丝巾独自上路"
        ]
      }
    ]
  }
}
", "path": "outline.json"}

