{"content": "{
  "act_one": {
    "description": "第一幕：开篇（0-1500字）- 建立世界观、引入主角和核心冲突",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "暴雨前的金属茧",
        "core_event": "南方湿热的雨季，陈锋用摩托车带走刚下岗的林晚。他在第一个县城买了第一对枕巾，谎称是“紧俏货”。",
        "emotional_tone": "压抑、潮湿、未知的紧张感",
        "key_scenes": [
          "工厂倒闭的公告栏前，陈锋骑着嘉陵摩托出现",
          "林晚第一次坐上摩托车后座，手不知道往哪放",
          "供销社买枕巾，陈锋的眼神闪躲"
        ]
      }
    ],
    "turning_point": "摩托车驶出熟悉的城市，进入未知的公路，两人命运捆绑。"
  },
  "act_two": {
    "description": "第二幕：挣扎（1500-5000字）- 冲突升级、主角陷入困境与情感升温",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "红色丝巾与流浪的锚",
        "core_event": "途经中部省份遭遇暴风雨，陈锋冒雨停车只为给她买一条红丝巾。她在地图上经过的城市画下第一颗心。",
        "emotional_tone": "激烈、浪漫、危险",
        "key_scenes": [
          "暴风雨中摩托车像一片树叶",
          "陈锋全身湿透买回红丝巾，笨拙地给她系上",
          "林晚在地图上偷偷画心，被雨水晕开"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "一万张婚床",
        "core_event": "到达黄河边的桥洞过夜。陈锋铺开所有积攒的鸳鸯枕巾，两人躺在“一万张婚床”上。他半开玩笑半认真地说出那个赌约。",
        "emotional_tone": "绝望中的极致浪漫、悲剧预警",
        "key_scenes": [
          "桥洞下铺满的鸳鸯枕巾，像一场荒诞的婚礼",
          "陈锋说出“摩托归你，我归摩托”的赌约",
          "两人在枕巾堆中沉默相拥，没有说破的爱意"
        ]
      }
    ],
    "turning_point": "赌约确立，情感达到顶峰，但现实的阴影逼近。"
  },
  "act_three": {
    "description": "第三幕：高潮+结局（5000-8000字）- X-Y化学反应爆发，BE结局",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "凛冬的告别",
        "core_event": "抵达北方，生意惨败（被骗）。陈锋为了不连累林晚，故意激怒她或趁她熟睡离开，独自去面对债主/危险，最终死在路上（或失踪）。林晚醒来只看到留下的摩托车和枕巾。",
        "emotional_tone": "冰冷、撕裂、无尽的悲凉",
        "key_scenes": [
          "北方寒风中，接头人老张的骗局揭穿",
          "陈锋最后的决绝眼神，他选择履行“我归摩托”",
          "林晚独自一人在雪地里，守着摩托车和一堆枕巾",
          "结局：林晚卖掉摩托，买了一张去深圳的车票，带着红丝巾独自上路"
        ]
      }
    ]
  }
}
